const PLUGIN_ID = "qwen-custom-voice-tts-plugin";
const DEFAULT_QWEN_TARGET_MODEL = "qwen3-tts-vc-2026-01-22";
const DEFAULT_COSY_TARGET_MODEL = "cosyvoice-v3.5-plus";

const normalizeBaseUrl = (baseUrl) => {
  return (baseUrl || "https://dashscope.aliyuncs.com/api/v1").replace(/\/+$/, "");
};

const shouldLog = (config) => {
  return !config || config.debug !== "no";
};

const log = (config, ...args) => {
  if (shouldLog(config)) {
    console.log("[Aliyun Custom Voice TTS]", ...args);
  }
};

const clamp = (value, min, max) => {
  return Math.min(max, Math.max(min, value));
};

const sleep = (ms) => {
  return new Promise((resolve) => setTimeout(resolve, ms));
};

const normalizeAudioUrl = (audioUrl) => {
  return audioUrl.replace(/^http:\/\//, "https://");
};

const shouldRetryDownload = (error) => {
  const transientCodes = [
    "ECONNRESET",
    "ETIMEDOUT",
    "ECONNABORTED",
    "EAI_AGAIN",
    "ENOTFOUND",
  ];
  const status = error && error.response && error.response.status;
  return transientCodes.includes(error && error.code) || status >= 500;
};

const postWithRetry = async (url, body, options, config, axios, label) => {
  const maxAttempts = clamp(
    parseInt((config && config.requestRetryCount) || "3", 10) || 3,
    1,
    5,
  );
  const timeout = clamp(
    parseInt((config && config.requestTimeout) || "90000", 10) || 90000,
    10000,
    300000,
  );

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      log(config, `${label} post`, {
        attempt,
        maxAttempts,
        timeout,
      });
      return await axios.post(url, body, {
        ...options,
        timeout,
      });
    } catch (error) {
      const retryable = shouldRetryDownload(error);
      log(config, `${label} post failed`, {
        attempt,
        maxAttempts,
        retryable,
        code: error && error.code,
        status: error && error.response && error.response.status,
        message: error && error.message,
      });
      if (!retryable || attempt >= maxAttempts) {
        throw error;
      }
      await sleep(500 * attempt);
    }
  }

  throw new Error(`${label} post failed`);
};

const downloadAudioWithRetry = async (audioUrl, config, axios) => {
  const safeAudioUrl = normalizeAudioUrl(audioUrl);
  const maxAttempts = clamp(
    parseInt((config && config.downloadRetryCount) || "3", 10) || 3,
    1,
    5,
  );
  const timeout = clamp(
    parseInt((config && config.downloadTimeout) || "90000", 10) || 90000,
    10000,
    300000,
  );

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      log(config, "download audio", {
        attempt,
        maxAttempts,
        timeout,
        urlProtocol: safeAudioUrl.split(":")[0],
      });
      const audioResponse = await axios.get(safeAudioUrl, {
        responseType: "arraybuffer",
        timeout,
      });
      const buffer = Buffer.from(audioResponse.data);
      log(config, "download audio success", {
        attempt,
        byteLength: buffer.length,
      });
      return buffer;
    } catch (error) {
      const retryable = shouldRetryDownload(error);
      log(config, "download audio failed", {
        attempt,
        maxAttempts,
        retryable,
        code: error && error.code,
        status: error && error.response && error.response.status,
        message: error && error.message,
      });
      if (!retryable || attempt >= maxAttempts) {
        throw error;
      }
      await sleep(500 * attempt);
    }
  }

  throw new Error("Download audio failed");
};

const normalizeLocale = (locale) => {
  if (!locale || locale === "zh") return "zh-CN";
  if (locale === "en") return "en-US";
  if (locale === "ja") return "ja-JP";
  if (locale === "ko") return "ko-KR";
  if (locale === "fr") return "fr-FR";
  if (locale === "de") return "de-DE";
  if (locale === "ru") return "ru-RU";
  if (locale === "pt") return "pt-PT";
  if (locale === "th") return "th-TH";
  if (locale === "id") return "id-ID";
  if (locale === "vi") return "vi-VN";
  return locale;
};

const parseListConfig = (value) => {
  if (!value) return [];
  if (Array.isArray(value)) return value.filter(Boolean);
  return String(value)
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
};

const getQwenTargetModel = (config) => {
  return config.qwenTargetModel || config.targetModel || config.model || DEFAULT_QWEN_TARGET_MODEL;
};

const getCosyTargetModel = (config) => {
  return config.cosyTargetModel || DEFAULT_COSY_TARGET_MODEL;
};

const getAudioPath = async (text, speed, dirPath, config) => {
  const path = require("path");
  const fs = require("fs");
  const format = config.provider === "cosyvoice" ? config.format || "wav" : "wav";
  const audioName = `${new Date().getTime()}.${format}`;
  const ttsDir = path.join(dirPath, "tts");

  if (!fs.existsSync(ttsDir)) {
    fs.mkdirSync(ttsDir);
  }

  const audioData = await getTTSAudio(text, speed, config);
  const audioPath = path.join(ttsDir, audioName);
  fs.writeFileSync(audioPath, audioData);
  return audioPath;
};

const getTTSAudio = async (text, speed, config) => {
  if (config.provider === "cosyvoice") {
    return await getCosyTTSAudio(text, speed, config);
  }
  return await getQwenTTSAudio(text, speed, config);
};

const getQwenTTSAudio = async (text, speed, config) => {
  const apiKey = config.apiKey || "";
  const model = config.model || getQwenTargetModel(config);
  const voiceName = config.voiceName || "";
  const baseUrl = normalizeBaseUrl(config.baseUrl);
  const axios = require("axios");

  if (!apiKey) {
    throw new Error("Missing DashScope apiKey");
  }
  if (!voiceName) {
    throw new Error("Missing Qwen custom voice");
  }

  const body = {
    model,
    input: {
      text,
      voice: voiceName,
      language_type: config.qwenLanguageType || "Chinese",
    },
    parameters: {
      stream: false,
    },
  };

  const speedDelta = Number(speed);
  if (!Number.isNaN(speedDelta) && speedDelta !== 0) {
    body.parameters.speech_rate = clamp(Math.round(speedDelta * 10), -500, 500);
  }

  log(config, "qwen synthesis request", {
    baseUrl,
    model,
    voiceName,
    languageType: body.input.language_type,
    textLength: text ? text.length : 0,
  });

  const response = await postWithRetry(
    `${baseUrl}/services/aigc/multimodal-generation/generation`,
    body,
    {
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
        "X-DashScope-DataInspection": "enable",
      },
    },
    config,
    axios,
    "qwen synthesis",
  );

  const audioUrl =
    response.data &&
    response.data.output &&
    response.data.output.audio &&
    response.data.output.audio.url;

  if (!audioUrl) {
    log(config, "qwen synthesis response has no audio url", response.data);
    throw new Error("No audio URL in Qwen TTS response");
  }

  log(config, "qwen synthesis response received audio url");
  return await downloadAudioWithRetry(audioUrl, config, axios);
};

const getCosyTTSAudio = async (text, speed, config) => {
  const apiKey = config.apiKey || "";
  const model = config.model || getCosyTargetModel(config);
  const voiceName = config.voiceName || "";
  const baseUrl = normalizeBaseUrl(config.baseUrl);
  const format = config.format || "wav";
  const sampleRate = parseInt(config.sampleRate || "24000", 10) || 24000;
  const volume = clamp(parseInt(config.volume || "50", 10) || 50, 0, 100);
  const pitch = clamp(parseFloat(config.pitch || "1.0") || 1.0, 0.5, 2.0);
  const speedDelta = Number(speed);
  const rate = clamp(
    Number.isNaN(speedDelta) ? 1.0 : (speedDelta + 100) / 100,
    0.5,
    2.0,
  );
  const languageHints = parseListConfig(config.cosyLanguageHints || config.languageHints);
  const axios = require("axios");

  if (!apiKey) {
    throw new Error("Missing DashScope apiKey");
  }
  if (!voiceName) {
    throw new Error("Missing CosyVoice custom voice");
  }

  const input = {
    text,
    voice: voiceName,
    format,
    sample_rate: sampleRate,
    volume,
    rate,
    pitch,
  };

  if (languageHints.length > 0) {
    input.language_hints = languageHints;
  }
  if (config.instruction) {
    input.instruction = config.instruction;
  }

  log(config, "cosyvoice synthesis request", {
    baseUrl,
    model,
    voiceName,
    format,
    sampleRate,
    rate,
    volume,
    pitch,
    languageHints,
    textLength: text ? text.length : 0,
  });

  const response = await postWithRetry(
    `${baseUrl}/services/audio/tts/SpeechSynthesizer`,
    {
      model,
      input,
    },
    {
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
    },
    config,
    axios,
    "cosyvoice synthesis",
  );

  const audioUrl =
    response.data &&
    response.data.output &&
    response.data.output.audio &&
    response.data.output.audio.url;

  if (!audioUrl) {
    log(config, "cosyvoice synthesis response has no audio url", response.data);
    throw new Error("No audio URL in CosyVoice TTS response");
  }

  log(config, "cosyvoice synthesis response received audio url");
  return await downloadAudioWithRetry(audioUrl, config, axios);
};

const listQwenVoices = async (config, axios) => {
  const apiKey = config.apiKey || "";
  const baseUrl = normalizeBaseUrl(config.baseUrl);
  const targetModel = getQwenTargetModel(config);
  const pageSize = clamp(parseInt(config.pageSize || "100", 10) || 100, 1, 100);
  const voices = [];
  let pageIndex = 0;
  let totalCount = null;

  log(config, "list qwen custom voices", {
    baseUrl,
    targetModel,
    pageSize,
  });

  do {
    const response = await postWithRetry(
      `${baseUrl}/services/audio/tts/customization`,
      {
        model: "qwen-voice-enrollment",
        input: {
          action: "list",
          page_size: pageSize,
          page_index: pageIndex,
        },
      },
      {
        headers: {
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json",
        },
      },
      config,
      axios,
      "qwen voice list",
    );

    const output = (response.data && response.data.output) || {};
    const pageVoices = Array.isArray(output.voice_list)
      ? output.voice_list
      : [];
    totalCount =
      typeof output.total_count === "number" ? output.total_count : totalCount;
    log(config, "list qwen custom voices page", {
      pageIndex,
      pageCount: pageVoices.length,
      totalCount,
    });
    voices.push(...pageVoices);

    if (pageVoices.length < pageSize) {
      break;
    }
    pageIndex += 1;
  } while (totalCount === null || voices.length < totalCount);

  return voices.map((voice) => ({
    name: voice.voice || voice.voice_id,
    gender: "unknown",
    locale: normalizeLocale(voice.language || voice.locale),
    displayName: `Qwen Custom Voice - ${voice.voice || voice.voice_id} (${voice.target_model || targetModel})`,
    plugin: PLUGIN_ID,
    config: {
      ...config,
      provider: "qwen",
      voiceName: voice.voice || voice.voice_id,
      model: voice.target_model || targetModel,
    },
  }));
};

const listCosyVoices = async (config, axios) => {
  const apiKey = config.apiKey || "";
  const baseUrl = normalizeBaseUrl(config.baseUrl);
  const targetModel = getCosyTargetModel(config);
  const prefix = config.cosyPrefix || config.prefix || "";
  const pageSize = clamp(parseInt(config.pageSize || "100", 10) || 100, 1, 100);
  const languageHints = parseListConfig(config.cosyLanguageHints || config.languageHints);
  const voices = [];
  let pageIndex = 0;

  log(config, "list cosyvoice custom voices", {
    baseUrl,
    targetModel,
    prefix,
    pageSize,
  });

  do {
    const input = {
      action: "list_voice",
      page_size: pageSize,
      page_index: pageIndex,
    };
    if (prefix) {
      input.prefix = prefix;
    }

    const response = await postWithRetry(
      `${baseUrl}/services/audio/tts/customization`,
      {
        model: "voice-enrollment",
        input,
      },
      {
        headers: {
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json",
        },
      },
      config,
      axios,
      "cosyvoice voice list",
    );

    const output = (response.data && response.data.output) || {};
    const pageVoices = Array.isArray(output.voice_list)
      ? output.voice_list
      : [];
    log(config, "list cosyvoice custom voices page", {
      pageIndex,
      pageCount: pageVoices.length,
    });
    voices.push(...pageVoices);

    if (pageVoices.length < pageSize) {
      break;
    }
    pageIndex += 1;
  } while (true);

  return voices
    .filter((voice) => {
      const voiceId = voice.voice_id || voice.voice;
      return (
        voiceId &&
        voice.status === "OK" &&
        (!targetModel || voiceId.indexOf(`${targetModel}-`) === 0)
      );
    })
    .map((voice) => {
      const voiceId = voice.voice_id || voice.voice;
      return {
        name: voiceId,
        gender: "unknown",
        locale: normalizeLocale(languageHints[0]),
        displayName: `CosyVoice Custom Voice - ${voiceId} (${targetModel})`,
        plugin: PLUGIN_ID,
        config: {
          ...config,
          provider: "cosyvoice",
          voiceName: voiceId,
          model: targetModel,
        },
      };
    });
};

const getTTSVoice = async (config) => {
  const apiKey = config.apiKey || "";
  const axios = require("axios");

  if (!apiKey) {
    throw new Error("Missing DashScope apiKey");
  }

  const results = [];
  const errors = [];

  try {
    results.push(...(await listCosyVoices(config, axios)));
  } catch (error) {
    errors.push(`CosyVoice: ${error && error.message ? error.message : error}`);
    log(config, "list cosyvoice custom voices failed", {
      message: error && error.message,
      status: error && error.response && error.response.status,
      data: error && error.response && error.response.data,
    });
  }

  try {
    results.push(...(await listQwenVoices(config, axios)));
  } catch (error) {
    errors.push(`Qwen: ${error && error.message ? error.message : error}`);
    log(config, "list qwen custom voices failed", {
      message: error && error.message,
      status: error && error.response && error.response.status,
      data: error && error.response && error.response.data,
    });
  }

  if (results.length === 0) {
    throw new Error(
      errors.length > 0
        ? `No Aliyun custom voices found. ${errors.join("; ")}`
        : "No Aliyun custom voices found for this API key",
    );
  }

  log(config, "custom voices loaded", {
    count: results.length,
    voices: results.map((voice) => voice.name),
  });

  return results;
};

global.getAudioPath = getAudioPath;
global.getTTSVoice = getTTSVoice;
